<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('task.view_own');verify_csrf();$pdo=staff_db();$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['task_id'];$status=$_POST['status'];$pdo->prepare("UPDATE tasks SET status=?,completed_at=IF(?='completed',NOW(),NULL) WHERE id=? AND assigned_to=?")->execute([$status,$status,$id,$staff['id']]);staff_redirect('staff/pages/tasks.php');}
$s=$pdo->prepare("SELECT * FROM tasks WHERE assigned_to=? ORDER BY FIELD(status,'in_progress','todo','waiting','completed','cancelled'),due_date");$s->execute([$staff['id']]);$rows=$s->fetchAll();
$pageTitle='My Tasks';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Work</p><h1>My tasks</h1></div></div><div class="task-grid"><?php foreach($rows as $r):?><article class="staff-panel task-card"><div class="rowtop"><span class="pill <?= h($r['priority']) ?>"><?= h($r['priority']) ?></span><span class="pill"><?= h(str_replace('_',' ',$r['status'])) ?></span></div><h2><?= h($r['title']) ?></h2><p><?= h($r['description']?:'') ?></p><small><?= $r['due_date']?h(date('j M Y, g:i A',strtotime($r['due_date']))):'No due date' ?></small><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= $r['id'] ?>"><select name="status"><option value="todo">To do</option><option value="in_progress">In progress</option><option value="waiting">Waiting</option><option value="completed">Completed</option></select><button class="btn">Update</button></form></article><?php endforeach;?></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
